import type { FileRef } from "@rcompat/fs";
import { addPackageToConfig, addPackageToGlobalConfig } from "#utils/config";

export default async function registerPowerup({
  name,
  isLocal,
  projectRoot,
}: {
  name: string;
  isLocal: boolean;
  projectRoot: FileRef;
}): Promise<void> {
